// export_symbol_map.rs - Export complete symbol map as JSON
// Generated by step4_bootstrap - Symbol Map Export

use split_decls_genesis::{
    find_rust_files_in_dependency_fast, extract_all_symbols_from_file_fast,
    get_rustc_dependencies, Symbol
};
use std::collections::HashMap;
use serde_json;

fn main() {
    println!("🗺️  Exporting complete symbol map to JSON...");
    
    let rustc_deps = get_rustc_dependencies().unwrap_or_default();
    let mut all_symbols = HashMap::new();
    let mut file_count = 0;
    
    for dep in &rustc_deps {
        let rust_files = find_rust_files_in_dependency_fast(&dep.path);
        println!("📦 {}: {} files", dep.name, rust_files.len());
        
        for file in rust_files {
            file_count += 1;
            if let Ok(symbols) = extract_all_symbols_from_file_fast(&file.to_string_lossy(), &dep.name) {
                for symbol in symbols {
                    // Use crate::filename::symbol to avoid conflicts between main.rs and build.rs
                    let filename = std::path::Path::new(&symbol.source_file)
                        .file_stem()
                        .and_then(|s| s.to_str())
                        .unwrap_or("unknown");
                    let qualified_name = format!("{}::{}::{}", symbol.crate_name, filename, symbol.name);
                    all_symbols.insert(qualified_name, symbol);
                }
            }
            
            if file_count % 100 == 0 {
                println!("  📊 Processed {} files, {} symbols", file_count, all_symbols.len());
            }
        }
    }
    
    println!("✅ Extracted {} total symbols from {} files", all_symbols.len(), file_count);
    
    // Export to JSON
    let json_output = serde_json::to_string_pretty(&all_symbols).expect("Failed to serialize symbols");
    std::fs::write("symbol_map.json", json_output).expect("Failed to write symbol_map.json");
    
    // Export summary stats
    let mut stats = HashMap::new();
    stats.insert("total_symbols", all_symbols.len());
    stats.insert("total_files", file_count);
    
    let mut crate_counts = HashMap::new();
    let mut type_counts = HashMap::new();
    
    for symbol in all_symbols.values() {
        *crate_counts.entry(symbol.crate_name.clone()).or_insert(0) += 1;
        *type_counts.entry(symbol.symbol_type.clone()).or_insert(0) += 1;
    }
    
    let summary = serde_json::json!({
        "stats": stats,
        "crate_distribution": crate_counts,
        "type_distribution": type_counts
    });
    
    let summary_json = serde_json::to_string_pretty(&summary).expect("Failed to serialize summary");
    std::fs::write("symbol_summary.json", summary_json).expect("Failed to write symbol_summary.json");
    
    println!("📄 Exported symbol_map.json ({} symbols)", all_symbols.len());
    println!("📊 Exported symbol_summary.json (stats)");
    
    // Show some key symbols
    println!("\n🔍 Key symbol lookups:");
    if let Some(var_symbol) = all_symbols.get("var") {
        println!("  ✅ var: {} in {}", var_symbol.symbol_type, var_symbol.source_file);
    } else {
        println!("  ❌ var: not found");
    }
    
    if let Some(main_symbol) = all_symbols.get("main") {
        println!("  ✅ main: {} in {}", main_symbol.symbol_type, main_symbol.source_file);
    } else {
        println!("  ❌ main: not found");
    }
    
    println!("  📋 env.rs symbols:");
    let env_symbols: Vec<_> = all_symbols.values()
        .filter(|s| s.source_file.contains("/env.rs"))
        .take(10)
        .collect();
    
    for symbol in env_symbols {
        println!("    - {}: {} ({})", symbol.name, symbol.symbol_type, symbol.source_file);
    }
}
